// The reaper's FRONTEND half — and it no longer decides anything.
//
// This hook used to own the whole policy: it polled, computed `panesToReap`, and invoked `pty_kill`.
// That put the bound on session count inside the renderer, which is both the most fragile part of the
// app and not the part that owns the sessions. MEASURED 2026-08-31: the webview was OOM-killed and the
// backend ran headless for fifteen minutes with SEVENTEEN sessions alive — eleven directors for
// projects nobody was working on, and fifteen `bsc-agent` processes that had never used a second of
// CPU. Nothing reaped them, because the only thing that reaped had died.
//
// The policy now lives in `console::pty::reap`, in the process that owns the PTYs, and runs whether or
// not a window exists. What is left here is the ONE input only the UI has — which panes the user can
// SEE — plus the user's configured thresholds, both REPORTED to the backend.
//
// WHICH PANES, PLURAL, AND NOT "FOCUSED". This reported a single pane id built from the console grid's
// `focusedPaneIdx`, and that is the wrong shape of answer twice over. Two surfaces show two different
// sessions at once (a console cell beside an open Glance morph), and a studio session, a graph session
// and a network architect are not console panes at all — so `should_reap`'s one unconditional
// protection was unreachable for every session the app owns. MEASURED on the live store:
// `focusedPaneIdx` was unset and the active workspace was `glance`, so the app reported NULL and
// nothing whatsoever was protected while the user worked in the graphs. Under the ten-second idle
// grace that is the whole of "system sessions in the components, algorithms and other graphs are
// ending".
//
// The answer comes from `TerminalHost`, which already computes it for its own re-parenting
// (`ownerClaim` + `claimIsOnScreen`) and is the only thing that knows whether a pane's terminal is
// really rendered — including that a kept-mounted, CSS-hidden page dock does not count.
//
// Reporting on a timer rather than only on change is deliberate: the backend expires the report
// (`FOCUS_REPORT_TTL_MS`) instead of latching it, so that a renderer which dies mid-session does not
// leave what it was showing protected forever. A live UI must therefore keep saying so, and the
// interval is set well inside that window.

import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { effectiveIdleMs, silenceCeilingMs } from "@/app/console/lib/idleReaper";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { onScreenPaneIdsNow } from "@/app/console/terminal/TerminalHost";
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";

/** Re-report what is on screen this often. Comfortably inside the backend's 30s report TTL, so a live
 *  UI never lapses into looking dead — while a UI that really is gone lapses within one TTL. */
const ONSCREEN_REPORT_MS = 5_000;

/** The backend's name for a reap it has already performed. */
const REAPED_EVENT = "pty-reaped";

export function useIdleReaper(): void {
  // THE OTHER HALF OF THE MOVE, and it was missing for one commit. The frontend reaper used to do
  // `pty_kill` AND `reapPane`; moving the policy to Rust kept the kill and dropped the store update,
  // so a backend-reaped pane went on rendering a live terminal over a dead PTY.
  //
  // The event is the backend REPORTING what it already did, not asking permission — so this only
  // mirrors it into the store, where `dormantPanes` swaps the terminal for a resume placeholder and
  // (since it is persisted) keeps the pane from relaunching on the next boot.
  useEffect(() => {
    const un = listen<string>(REAPED_EVENT, (e) => {
      const paneId = typeof e.payload === "string" ? e.payload : "";
      if (paneId) useAppStore.getState().reapPane(paneId);
    });
    return () => {
      void un.then((f) => f());
    };
  }, []);

  // The user's configured thresholds, reported so the Settings control actually governs the decision.
  // Without this the backend would run its own defaults while Settings displayed a number that changed
  // nothing — a control that visibly does nothing is worse than no control.
  const idleGraceMs = useAppStore((s) => effectiveIdleMs(s.idleReaper));
  const ceilingMs = useAppStore((s) => silenceCeilingMs(s.idleReaper));
  const enabled = useAppStore((s) => s.idleReaper.enabled);
  useEffect(() => {
    // Disabled reaping is expressed as thresholds the sweep can never reach, rather than as a second
    // on/off flag in the backend: one representation of "off", and the sweep keeps running so its
    // logging and its activity view stay truthful.
    fireInvoke("pty_set_reap_policy", {
      idleGraceMs: enabled ? idleGraceMs : Number.MAX_SAFE_INTEGER,
      silenceCeilingMs: enabled ? ceilingMs : Number.MAX_SAFE_INTEGER,
    });
  }, [enabled, idleGraceMs, ceilingMs]);

  usePoll(
    () => {
      const s = useAppStore.getState();
      // RESOLVED THROUGH `paneIdFor`, never built as `t<tab>p<pane>`. The positional form is the
      // RETIRED pane id — panes are identity-keyed (`twitter-clone-test:director`) — so a positional
      // comparison matched nothing and the old focus guard was inert for every real pane.
      const focused =
        s.focusedPaneIdx >= 0
          ? paneIdFor(s.tabs[s.activeTabIdx], s.activeTabIdx, s.focusedPaneIdx)
          : null;
      // THE UNION, and the console pane is kept as its own term rather than left to the host.
      // `focusedPaneIdx` is the keyboard cursor within the grid; a background console tab's cell is a
      // live, non-parked, `visible` claim that simply is not rendered, so the host correctly excludes
      // it while the store correctly still calls it focused. Neither answer subsumes the other, and
      // both are reasons not to reap.
      const onScreen = new Set(onScreenPaneIdsNow());
      if (focused) onScreen.add(focused);
      fireInvoke("pty_report_onscreen", { paneIds: [...onScreen].sort() });
    },
    ONSCREEN_REPORT_MS,
    [],
    { immediate: true },
  );
}

